import type { Vehicle } from "../types";
import { useAppStore } from "../store/useAppStore";
import { cad, km, kw } from "../lib/format";
import { ConfidenceBadge } from "./ConfidenceBadge";
import { TERM, POWERTRAIN_PLAIN, PROTOCOL_PLAIN } from "../lib/labels";

export function VehicleRow({ vehicle }: { vehicle: Vehicle }) {
  const { compareIds, toggleCompare, plainMode } = useAppStore();
  const isSelected = compareIds.includes(vehicle.id);
  const atCap = compareIds.length >= 4 && !isSelected;

  const powertrainLabel = plainMode
    ? (POWERTRAIN_PLAIN[vehicle.powertrain] ?? vehicle.powertrain)
    : vehicle.powertrain;

  const protocolLabel = plainMode
    ? (PROTOCOL_PLAIN[vehicle.range_protocol] ?? vehicle.range_protocol)
    : vehicle.range_protocol;

  return (
    <div
      className={`group flex items-center gap-4 px-6 py-3 border-l-2 transition hover:bg-ink-700/40 ${
        isSelected
          ? "border-l-accent-blue bg-accent-blue/5"
          : "border-l-transparent"
      }`}
    >
      <div className="flex-1 min-w-0">
        <div className="flex items-baseline gap-2">
          <span className="font-display text-base text-ink-100">
            {vehicle.model}
          </span>
          <span className="text-xs text-ink-400">
            {vehicle.generation_label}
          </span>
          <span className="text-xs text-ink-300">· {vehicle.trim_label}</span>
          <ConfidenceBadge level={vehicle.overall_confidence} compact />
        </div>
        <div className="flex flex-wrap gap-x-4 gap-y-0.5 text-xs text-ink-400 mt-0.5">
          <span>
            <span className="text-ink-300">{powertrainLabel}</span> ·{" "}
            {vehicle.body_style} · {vehicle.drivetrain_variant === "AWD" ? "AWD" : "RWD/FWD"}
          </span>
          <span>
            {plainMode ? TERM.range.plain : TERM.range.geek}:{" "}
            <span className="text-ink-100">{km(vehicle.range_km.value)}</span>{" "}
            ({protocolLabel})
          </span>
          <span>
            {plainMode ? TERM.peakDc.plain : TERM.peakDc.geek}:{" "}
            <span className="text-ink-100">{kw(vehicle.dc_charge_kw_max.value)}</span>
          </span>
          <span>
            {plainMode ? TERM.port.plain : TERM.port.geek}:{" "}
            <span className="text-ink-100">{vehicle.port_type}</span>
          </span>
          <span>
            {plainMode ? TERM.msrp.plain : TERM.msrp.geek}:{" "}
            <span className="text-ink-100">{cad(vehicle.msrp_cad.value)}</span>
          </span>
        </div>
      </div>

      <button
        disabled={atCap}
        onClick={() => toggleCompare(vehicle.id)}
        className={`px-3 py-1.5 rounded text-xs font-medium transition whitespace-nowrap ${
          isSelected
            ? "bg-accent-blue text-white"
            : atCap
              ? "bg-ink-700 text-ink-500 cursor-not-allowed"
              : "bg-ink-700 text-ink-200 hover:bg-ink-600"
        }`}
        title={atCap ? "Compare tray full (max 4)" : undefined}
        aria-label={
          isSelected
            ? `Remove ${vehicle.model} from comparison`
            : atCap
              ? "Compare tray full (max 4 vehicles)"
              : `Add ${vehicle.model} to comparison`
        }
      >
        {isSelected ? "✓ Comparing" : atCap ? "Tray full (4)" : "Add to compare"}
      </button>
    </div>
  );
}

import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { Powertrain, BodyStyle, DrivetrainVariant } from "../types";
import { DEBUG_ENABLED, debugLog } from "../lib/debugLog";

export interface Filters {
  powertrain: Powertrain[] | "all";
  body_style: BodyStyle[] | "all";
  drivetrain: DrivetrainVariant[] | "all";
  max_price_cad: number | null;
  min_range_km: number | null;
  search: string;
}

export type TouTier = "off_peak" | "mid_peak" | "on_peak";

export const TOU_RATES: Record<TouTier, { label: string; rate: number }> = {
  off_peak: { label: "Off-peak (9.2 ¢/kWh)", rate: 0.092 },
  mid_peak: { label: "Mid-peak (13.6 ¢/kWh)", rate: 0.136 },
  on_peak: { label: "On-peak (17.9 ¢/kWh)", rate: 0.179 },
};

interface AppState {
  // Filters & compare
  filters: Filters;
  compareIds: string[]; // max 4
  setFilter: <K extends keyof Filters>(key: K, value: Filters[K]) => void;
  resetFilters: () => void;
  toggleCompare: (id: string) => void;
  clearCompare: () => void;

  // Thermal slider state
  temp_c: number; // -40..+40
  hvac_on: boolean;
  speed_kph: number;
  preconditioned: Record<string, boolean>; // vehicleId -> bool
  setTemp: (c: number) => void;
  setHvacOn: (v: boolean) => void;
  setSpeed: (v: number) => void;
  setPreconditioned: (id: string, v: boolean) => void;
  resetThermal: () => void;

  // Electricity rate (Ontario TOU)
  touTier: TouTier;
  setTouTier: (tier: TouTier) => void;

  // Plain / Geek display mode (mom mode)
  plainMode: boolean;
  setPlainMode: (v: boolean) => void;
}

const DEFAULT_FILTERS: Filters = {
  powertrain: "all",
  body_style: "all",
  drivetrain: "all",
  max_price_cad: null,
  min_range_km: null,
  search: "",
};

export const useAppStore = create<AppState>()(
  persist(
    (set) => ({
      filters: DEFAULT_FILTERS,
      compareIds: [],
      setFilter: (key, value) =>
        set((s) => ({ filters: { ...s.filters, [key]: value } })),
      resetFilters: () => set({ filters: DEFAULT_FILTERS }),
      toggleCompare: (id) =>
        set((s) => {
          if (s.compareIds.includes(id)) {
            return { compareIds: s.compareIds.filter((x) => x !== id) };
          }
          if (s.compareIds.length >= 4) return s;
          return { compareIds: [...s.compareIds, id] };
        }),
      clearCompare: () => set({ compareIds: [] }),

      // Thermal defaults: 20 °C baseline, HVAC off, highway speed.
      temp_c: 20,
      hvac_on: false,
      speed_kph: 100,
      preconditioned: {},
      setTemp: (c) => set({ temp_c: Math.max(-40, Math.min(40, c)) }),
      setHvacOn: (v) => set({ hvac_on: v }),
      setSpeed: (v) => set({ speed_kph: Math.max(40, Math.min(130, v)) }),
      setPreconditioned: (id, v) =>
        set((s) => ({ preconditioned: { ...s.preconditioned, [id]: v } })),
      resetThermal: () =>
        set({ temp_c: 20, hvac_on: false, speed_kph: 100, preconditioned: {} }),

      // Electricity rate — Ontario Hydro One TOU 2026, default mid-peak.
      touTier: "mid_peak",
      setTouTier: (tier) => set({ touTier: tier }),

      // Plain / Geek display mode.
      plainMode: false,
      setPlainMode: (v) => set({ plainMode: v }),
    }),
    {
      name: "ev-store-v1",
      // Persist compare tray, filters, thermal settings, rate, and display mode — but not actions.
      partialize: (s) => ({
        compareIds: s.compareIds,
        filters: s.filters,
        temp_c: s.temp_c,
        hvac_on: s.hvac_on,
        speed_kph: s.speed_kph,
        touTier: s.touTier,
        plainMode: s.plainMode,
      }),
    },
  ),
);

// Debug-mode store change logger. No-op when VITE_DEBUG != "1".
if (DEBUG_ENABLED) {
  const PERSISTED_KEYS = [
    "compareIds",
    "filters",
    "temp_c",
    "hvac_on",
    "speed_kph",
    "touTier",
    "plainMode",
  ] as const;
  type Key = (typeof PERSISTED_KEYS)[number];
  let prev = useAppStore.getState();
  useAppStore.subscribe((next) => {
    const changed: Record<string, { before: unknown; after: unknown }> = {};
    for (const k of PERSISTED_KEYS) {
      if (prev[k as Key] !== next[k as Key]) {
        changed[k] = { before: prev[k as Key], after: next[k as Key] };
      }
    }
    if (Object.keys(changed).length > 0) {
      debugLog("store", "state_change", changed);
    }
    prev = next;
  });
}

// Thermal / physics model for EV range, capacity, and DC-charging behavior
// under ambient temperature and preconditioning state.
//
// Purpose: given a vehicle's published specs and the current slider state
// (ambient °C, preconditioned y/n, HVAC on/off), return physically-grounded
// adjusted range, usable kWh, peak DC kW, and efficiency.
//
// Design principles (per scientific_rigor feedback memory):
//   * Every parameter comes from a published, citable source.
//   * Confidence of the output is derived from confidence of inputs AND the
//     inherent uncertainty of the physics model in the operating region.
//   * The function is pure, deterministic, and fully unit-testable.
//   * At slider extremes (-40 °C, +40 °C) confidence degrades to Low
//     automatically because real-world data is sparse out there.
//
// Sources informing the default curves (accessed 2026-04-23):
//   - Geotab "Winter EV Range Loss" dataset
//     https://www.geotab.com/blog/ev-range/
//   - Recurrent Auto "The real effect of cold weather on EV range" (2024)
//     https://www.recurrentauto.com/research/winter-ev-range-loss
//   - Fastned "Real-world charging speed data" dashboard
//     https://support.fastned.nl/
//   - Bjorn Nyland, 1000 km Challenge normalized results (YouTube channel)
//     https://www.youtube.com/@BjornNyland
//   - P3 Group charging-curve tests
//     https://www.p3-group.com/en/p3-charging-index/
//
// If you find a vehicle where the model disagrees with observed data by
// more than ~8%, update this vehicle's `thermal_profile` override (Phase 3
// task) or the anchor curves below.

